class Solution {
public:
    int cherryPickup(vector<vector<int>>& grid) {
        int n = grid.size();
        vector<vector<int>> dp(n, vector<int>(n, -1));
        dp[0][0] = grid[0][0];
        for (int step = 1; step < 2 * n - 1; ++step) {
            vector<vector<int>> nxt(n, vector<int>(n, -1));
            for (int r1 = max(0, step - (n - 1)); r1 <= min(n - 1, step); ++r1) {
                int c1 = step - r1;
                if (grid[r1][c1] == -1) continue;
                for (int r2 = r1; r2 <= min(n - 1, step); ++r2) {
                    int c2 = step - r2;
                    if (grid[r2][c2] == -1) continue;
                    int prevMax = -1;
                    for (int dr1 : {0, 1}) {
                        for (int dr2 : {0, 1}) {
                            int pr1 = r1 - dr1, pr2 = r2 - dr2;
                            if (pr1 >= 0 && pr2 >= 0 && dp[pr1][pr2] != -1) {
                                prevMax = max(prevMax, dp[pr1][pr2]);
                            }
                        }
                    }
                    if (prevMax != -1) {
                        int cherries = (r1 == r2) ? grid[r1][c1] : grid[r1][c1] + grid[r2][c2];
                        nxt[r1][r2] = prevMax + cherries;
                    }
                }
            }
            dp = move(nxt);
        }
        return max(0, dp[n - 1][n - 1]);
    }
};

class Solution {
    public int cherryPickup(int[][] grid) {
        int n = grid.length;
        int[][] dp = new int[n][n];
        for (int[] row : dp) Arrays.fill(row, -1);
        dp[0][0] = grid[0][0];
        for (int step = 1; step < 2 * n - 1; step++) {
            int[][] nxt = new int[n][n];
            for (int[] row : nxt) Arrays.fill(row, -1);
            for (int r1 = Math.max(0, step - (n - 1)); r1 <= Math.min(n - 1, step); r1++) {
                int c1 = step - r1;
                if (grid[r1][c1] == -1) continue;
                for (int r2 = r1; r2 <= Math.min(n - 1, step); r2++) {
                    int c2 = step - r2;
                    if (grid[r2][c2] == -1) continue;
                    int prevMax = -1;
                    for (int dr1 = 0; dr1 <= 1; dr1++) {
                        for (int dr2 = 0; dr2 <= 1; dr2++) {
                            int pr1 = r1 - dr1, pr2 = r2 - dr2;
                            if (pr1 >= 0 && pr2 >= 0 && dp[pr1][pr2] != -1) {
                                prevMax = Math.max(prevMax, dp[pr1][pr2]);
                            }
                        }
                    }
                    if (prevMax != -1) {
                        int cherries = (r1 == r2) ? grid[r1][c1] : grid[r1][c1] + grid[r2][c2];
                        nxt[r1][r2] = prevMax + cherries;
                    }
                }
            }
            dp = nxt;
        }
        return Math.max(0, dp[n - 1][n - 1]);
    }
}

var cherryPickup = function(grid) {
    const n = grid.length;
    let dp = Array.from({ length: n }, () => new Array(n).fill(-1));
    dp[0][0] = grid[0][0];
    for (let step = 1; step < 2 * n - 1; step++) {
        const nxt = Array.from({ length: n }, () => new Array(n).fill(-1));
        for (let r1 = Math.max(0, step - (n - 1)); r1 <= Math.min(n - 1, step); r1++) {
            const c1 = step - r1;
            if (grid[r1][c1] === -1) continue;
            for (let r2 = r1; r2 <= Math.min(n - 1, step); r2++) {
                const c2 = step - r2;
                if (grid[r2][c2] === -1) continue;
                let prevMax = -1;
                for (const dr1 of [0, 1]) {
                    for (const dr2 of [0, 1]) {
                        const pr1 = r1 - dr1, pr2 = r2 - dr2;
                        if (pr1 >= 0 && pr2 >= 0 && dp[pr1][pr2] !== -1) {
                            prevMax = Math.max(prevMax, dp[pr1][pr2]);
                        }
                    }
                }
                if (prevMax !== -1) {
                    const cherries = (r1 === r2) ? grid[r1][c1] : grid[r1][c1] + grid[r2][c2];
                    nxt[r1][r2] = prevMax + cherries;
                }
            }
        }
        dp = nxt;
    }
    return Math.max(0, dp[n - 1][n - 1]);
